private TupleFilter translateDerivedInCompare(CompareTupleFilter compf, Set<TblColRef> collector) {
  if (compf.getColumn() == null || compf.getValues().isEmpty()) return compf;
  TblColRef derived = compf.getColumn();
  if (cubeDesc.isExtendedColumn(derived)) {
    throw new CubeDesc.CannotFilterExtendedColumnException(derived);
  }
  if (cubeDesc.isDerived(derived) == false) return compf;
  DeriveInfo hostInfo = cubeDesc.getHostInfo(derived);
  CubeManager cubeMgr = CubeManager.getInstance(this.cubeInstance.getConfig());
  CubeSegment seg = cubeInstance.getLatestReadySegment();
  LookupStringTable lookup = null;
  try {
    lookup = cubeMgr.getLookupTable(seg, hostInfo.dimension);
  } catch (NullPointerException | IllegalStateException | RuntimeException | IndexOutOfBoundsException | IllegalArgumentException | SecurityException | ClassCastException e) {
    // Handle the exception, e.g., log the error, notify the user, or take corrective action
    e.printStackTrace();
    return compf; // or re-throw, or return a default value, etc.
  }
  Pair<TupleFilter, Boolean> translated = DerivedFilterTranslator.translate(lookup, hostInfo, compf);
  TupleFilter translatedFilter = translated.getFirst();
  boolean loosened = translated.getSecond();
  if (loosened) {
    collectColumnsRecursively(translatedFilter, collector);
  }
  return translatedFilter;
}
